function main(): void {
  const m = new Map<string, any>();
  m.set("m", m);
  console.log(m.get("m") === m);
  const s = new Set<any>();
  s.add(s);
  console.log(s.has(s));
  const arr: any[] = [];
  const m2 = new Map<string, any>();
  m2.set("a", arr);
  arr.push(1);
  console.log(m2.get("a") === arr, m2.get("a").length);
}
